`,paraId:0,tocIndex:1},{value:`/**
 * title: \u81EA\u5B9A\u4E49rules
 * hideActions: ['CSB', 'EXTERNAL']
 */
import * as React from 'react';
import { Form, useForm, FormItem, Input, validateMessages } from '@baic/yolk-miniprogram';

export default () => {
  const [form] = useForm();
  const { createFormItem } = form;
  const rules = React.useCallback((_, { validator, schema }) => ({
    validator: async (rule, value) => {
       // \u81EA\u5B9A\u4E49\u5199\u6CD5
      if (value.length <= 2) {
        return Promise.reject('\u957F\u5EA6\u4E0D\u591F2');
      }
      // \u4F7F\u7528zod\u65B9\u6CD5
      try {
        await schema(({ zod }) => zod.string().min(5)).validateAsync(value);
      } catch (error) {
        return Promise.reject('\u957F\u5EA6\u4E0D\u591F3');
      }
      if (schema(({ zod }) => zod.string().min(6)).validate(value).error) {
        return Promise.reject('\u957F\u5EA6\u4E0D\u591F6');
      }
      // \u4F7F\u7528\u5185\u7F6E\u7684validator\u65B9\u6CD5
      if (!validator.mobile(value)) {
        return Promise.reject(validateMessages.mobile);
      }
    },
  }), []);
  return (
    <Form form={form}>
      {createFormItem({ name: 'Input1', rules })(<Input />)}
      <FormItem name="Input2" rules={rules}><Input /></FormItem>
      <Form.Item name="Input3" rules={rules}><Input /></Form.Item>
    </Form>
  );
};
